package db

// Not generated by sqlc: kept beside its output while internal/db is
// divided into the modules' stores (docs/migration.md, section 5).

// Conn is what q runs its queries on: the pool, or the transaction q was
// made for with WithTx. A module's store that must write within that
// transaction runs on it (database.Conn).
func (q *Queries) Conn() DBTX { return q.db }
